header-includes:
#let antwortlinie(width: 4.5cm) = box(width: width, height: 6mm, fill: rgb("#eeeeee"), baseline: 1.5mm)
#let diagnose_smiley(stufe) = box(width: 4mm, height: 4mm, baseline: 0.6mm)[
  #let farbe = if stufe == "ueben" { rgb("#ef7770") } else if stufe == "festigen" { rgb("#f6d65b") } else { rgb("#78c98b") }
  #circle(radius: 2mm, fill: farbe, stroke: 0.5pt + rgb("#172033"))
  #place(top + left, dx: 1.05mm, dy: 1.1mm, circle(radius: 0.225mm, fill: rgb("#172033"), stroke: none))
  #place(top + left, dx: 2.5mm, dy: 1.1mm, circle(radius: 0.225mm, fill: rgb("#172033"), stroke: none))
  #let y = if stufe == "ueben" { 3mm } else if stufe == "festigen" { 2.7mm } else { 2.4mm }
  #let control = if stufe == "ueben" { 2mm } else if stufe == "festigen" { 2.7mm } else { 3.4mm }
  #place(top + left, curve(
    stroke: 0.6pt + rgb("#172033"),
    curve.move((1mm, y)),
    curve.cubic((1.5mm, control), (2.5mm, control), (3mm, y)),
  ))
]
